property.value:
let $read := function($e) {
      exists($e[self::MethodCall][@MethodName = ('readString', 'readFileToString', 'readAllBytes')]
             | $e[self::ConstructorCall][ClassType/@SimpleName = 'String']
                 [ArgumentList/*[1][self::MethodCall][@MethodName = ('readAllBytes', 'readFileToByteArray', 'readBytes')]]
             | $e[self::MethodCall][@MethodName = 'toString'][ArgumentList/@Size = (1, 2)]
                 [*[1][self::TypeExpression/ClassType[@SimpleName = 'IOUtils']]])
    },
    $steps := ('trim', 'strip', 'stripTrailing', 'stripLeading'),
    $base := function($e) {
      $read($e) or exists($e[self::MethodCall][@MethodName = $steps][ArgumentList/@Size = 0][$read(*[1])])
    },
    $newline := function($e) { exists($e[self::StringLiteral][@Image = '"\n"']) },
    $text := function($e) {
      $base($e) or exists($e[self::VariableAccess][let $name := @Name return
        ancestor::*[self::MethodDeclaration or self::ConstructorDeclaration or self::LambdaExpression or self::Initializer][1]
          //LocalVariableDeclaration/VariableDeclarator[VariableId/@Name = $name][$base(*[2])]
          [not(ancestor::*[self::MethodDeclaration or self::ConstructorDeclaration or self::LambdaExpression or self::Initializer][1]
               //AssignmentExpression[*[1][self::VariableAccess[@Name = $name]]])]])
    }
return //MethodCall[@MethodName = ('split', 'indexOf', 'lastIndexOf')][$newline(ArgumentList/*[1])][ArgumentList/@Size = 1]
  [$text(*[1])]
  [not(ancestor::*[self::MethodDeclaration or self::ConstructorDeclaration or self::LambdaExpression or self::Initializer][1]
        //StringLiteral[matches(@Image, '\\r|\\R|\\u2028')])]
